        ["Reports"] = "Informes",
        ["Dashboards over the OData entity sets with charts, KPIs, tables and filters, aggregated on the server."] = "Paneles sobre los conjuntos de entidades OData con gráficos, KPI, tablas y filtros, agregados en el servidor.",
        ["For apps whose users want to see their numbers."] = "Para apps cuyos usuarios quieren ver sus cifras.",
