        [".mp4, .webm, .ogg and .mov play as video"] = ".mp4, .webm, .ogg y .mov se reproducen como vídeo",
        ["Large videos slow the first sign-in"] = "Los vídeos grandes ralentizan el primer inicio de sesión",
